INSERT INTO "public"."sector_trigger_skipped" ("id", "log_id", "ticker", "reason", "created_at") VALUES ('055e3df2-3965-42ee-ba72-2d9225c4c0d9', '93a52bb7-fda1-4d45-8b20-21812bcfb569', 'HEXA.JK', 'Perubahan direksi rutin tanpa aksi korporasi strategis yang berdampak material terhadap valuasi jangka pendek.', '2026-09-21 01:00:15.072671+00'), ('267e9535-2e51-4029-9519-26bce6b39088', '0a2bebac-66e4-4d03-8239-b7aeed47405d', 'IDEA.JK', 'Tidak memiliki simbol resmi di daftar yang valid untuk trading.', '2026-09-17 06:49:29.615867+00'), ('2760f089-4b38-4a52-b907-93bbc16ab1a5', '93a52bb7-fda1-4d45-8b20-21812bcfb569', 'KLBF.JK', 'Hanya disebut dalam konteks sentimen pasar umum, bukan berdasarkan aksi korporasi emiten itu sendiri.', '2026-09-21 01:00:15.072671+00'), ('31e4392c-a9c4-46f1-b790-d607babc4250', '0a2bebac-66e4-4d03-8239-b7aeed47405d', 'EPAC.JK', 'Penutupan segmen bisnis utama adalah sinyal restrukturisasi berisiko tinggi.', '2026-09-17 06:49:29.615867+00'), ('3630d172-69fc-49b8-bc42-d02c60f5d3a7', '24ecd9fd-0ded-4ab5-9a50-3377039fd8e9', 'EPAC.JK', 'Penghentian segmen usaha utama mengindikasikan risiko operasional yang tinggi.', '2026-09-17 07:55:02.169636+00'), ('3d392cee-47d1-40d6-8283-24861245f6b8', '71ca3d88-32c0-406d-9a03-1ae7e9a7074d', 'IFII.JK', 'Dividen interim bersifat rutin, kurang memiliki dampak katalis transformasional dibanding opsi lainnya.', '2026-09-18 12:11:19.121687+00'), ('43eb8a35-f086-4844-8c42-b192110c192b', '71ca3d88-32c0-406d-9a03-1ae7e9a7074d', 'SCNP.JK', 'Penjualan saham treasury memiliki dampak dilusi dan kurang edukatif dibanding aksi korporasi strategis lainnya.', '2026-09-18 12:11:19.121687+00'), ('703303e7-0583-4cef-8961-c4f138140d14', '93a52bb7-fda1-4d45-8b20-21812bcfb569', 'BULL.JK', 'Hanya sekadar sentimen makro, tidak memiliki katalis aksi korporasi konkret yang mendukung fundamental emiten secara spesifik.', '2026-09-21 01:00:15.072671+00'), ('70833475-f676-4fca-9bbb-df76f26274fd', '0a2bebac-66e4-4d03-8239-b7aeed47405d', 'IRSX.JK', 'Laporan keuangan rutin, kurang katalis aksi korporasi yang mendesak.', '2026-09-17 06:49:29.615867+00'), ('73bff35c-2d80-4ff7-9533-e623ff6d72c8', '82361f38-7a9a-4de9-b049-ff9f9010f2d4', 'IFII.JK', 'Dividen interim rutin, kurang memiliki dampak katalis transformatif dibandingkan emiten lainnya.', '2026-09-18 07:01:18.866326+00'), ('8aad74eb-1093-4322-9ced-b7e50f93b51d', '82361f38-7a9a-4de9-b049-ff9f9010f2d4', 'INET.JK', 'Skala akuisisi kurang signifikan dan profil risiko emiten masih spekulatif.', '2026-09-18 07:01:18.866326+00'), ('9112112b-bfcc-4bad-ab64-740b48fa71a6', '511a2ed6-1f72-4f18-b362-ff8d483a5555', 'MBMA.JK', 'Program buyback adalah aksi positif, namun kalah signifikansi dibanding aksi M&A strategis pada emiten lain.', '2026-09-18 07:09:08.030811+00'), ('9224facc-d6f5-4bec-a27d-493f3ae97bea', '6b73e037-ad0f-4943-8c10-a1842c6df0c6', 'IRSX.JK', 'Laporan keuangan rutin tanpa adanya aksi korporasi strategis yang lebih mendesak untuk watchlist.', '2026-09-18 03:17:27.149915+00'), ('9cc5a233-2977-46b4-9d4c-bb1cc8ae7473', '82361f38-7a9a-4de9-b049-ff9f9010f2d4', 'IRSX.JK', 'Laporan keuangan rutin meskipun ada kenaikan laba, belum cukup kuat dibanding aksi korporasi M&A.', '2026-09-18 07:01:18.866326+00'), ('9d4d354f-77af-41f0-9041-56804b66421a', '71ca3d88-32c0-406d-9a03-1ae7e9a7074d', 'KKGI.JK', 'Prioritas diversifikasi sektor; sudah terwakili oleh emiten energi dengan katalis lebih kuat (PTRO/BYAN).', '2026-09-18 12:11:19.121687+00'), ('a48b1a23-4c32-4a01-8713-2e4f351770e0', '0a2bebac-66e4-4d03-8239-b7aeed47405d', 'KLBF.JK', 'Berita buyback kontradiktif antara cancel dan reinstate, menciptakan ketidakpastian manajemen.', '2026-09-17 06:49:29.615867+00'), ('a7f879ae-2f9f-4ee7-8fa8-f6253836a326', '511a2ed6-1f72-4f18-b362-ff8d483a5555', 'IFII.JK', 'Dividen interim rutin, kurang memiliki katalis pertumbuhan transformatif dibandingkan pilihan lain.', '2026-09-18 07:09:08.030811+00'), ('bac32d8a-9964-4b92-89f5-71b012482744', '24ecd9fd-0ded-4ab5-9a50-3377039fd8e9', 'IDEA.JK', 'Tidak memiliki ticker resmi yang valid dalam daftar simbol.', '2026-09-17 07:55:02.169636+00'), ('c0831cb8-27ea-4db7-a068-db4998c1c34c', '71ca3d88-32c0-406d-9a03-1ae7e9a7074d', 'MBMA.JK', 'Program buyback adalah aksi korporasi positif, namun kalah urgensi dibanding aksi M&A dan lonjakan laba drastis lainnya.', '2026-09-18 12:11:19.121687+00'), ('c669b0f1-03c9-4318-8a46-dc41d1fc04be', '511a2ed6-1f72-4f18-b362-ff8d483a5555', 'IRSX.JK', 'Laporan keuangan rutin, tidak ada aksi korporasi strategis yang mendesak.', '2026-09-18 07:09:08.030811+00'), ('c95fe219-16b0-4462-b217-5bc365666173', '24ecd9fd-0ded-4ab5-9a50-3377039fd8e9', 'KLBF.JK', 'Berita kontradiktif (batal vs lanjut buyback) menciptakan ketidakpastian manajemen.', '2026-09-17 07:55:02.169636+00'), ('ef60de98-0535-460a-b241-dfc5248fa092', '24ecd9fd-0ded-4ab5-9a50-3377039fd8e9', 'IRSX.JK', 'Kinerja keuangan rutin, kurang katalis aksi korporasi yang bersifat transformatif.', '2026-09-17 07:55:02.169636+00'), ('fa2a48a5-ebc1-43f4-92f5-336c0260c72e', '6b73e037-ad0f-4943-8c10-a1842c6df0c6', 'KKGI.JK', 'Dividen rutin tidak memberikan dampak signifikan dibandingkan katalis M&A dan buyback pada emiten lain.', '2026-09-18 03:17:27.149915+00');